  Local Notation pd_memset := (@LbA_DPdK.pd_memset HCEIL H HHbp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 aw F fc m1 ds pcons icount lo ff fp LF DSA DSW DSO DS8 DSV DSH DSM PCA PCO PC8 PCC DISJ ICN STK CEIL LO SPHI SPOBJ FFR FSB_OK FFDS FFPC FPPC FPDS HULL FRW FSV FSW FLW AC1 LV1) (only parsing).
  Local Notation fr_app := (@LbA_DPdK.fr_app HCEIL H sp m1 ds pcons icount lo ff fp ICN STK CEIL LO SPHI FFR FSB_OK) (only parsing).
